return [{ json: {
  ...vars,
  durationSeconds: Math.round(dur * 10) / 10,
  durationMMSS:    `${String(mm).padStart(2,'0')}:${String(ss).padStart(2,'0')}`,
  wordCount,
  wpm,
  scriptText,
  voicePackage
} }];

const fs   = require('fs');
const vars = $input.first().json;
const sys  = fs.readFileSync('/Users/jneal/n8n_projects/ruins_untold_system_prompts/media_placement_agent.md', 'utf-8');

const slimPackage = {
  topic:                          vars.voicePackage.topic,
  estimated_total_runtime_seconds: vars.voicePackage.estimated_total_runtime_seconds,
  segments: (vars.voicePackage.segments || []).map(s => ({
    segment_id:                 s.segment_id,
    act:                        s.act,
    sequence:                   s.sequence,
    word_count:                 s.word_count,
    estimated_duration_seconds: s.estimated_duration_seconds,
    narration_text:             s.narration_text
  }))
};

const authoritative_duration = vars.transcript
  ? vars.transcript.total_duration_seconds
  : vars.durationSeconds;

// Filter transcript words to sentence-boundary words only (ending with . ? !)
// The agent uses these to find precise scene cut points — it does not need every word.
const slimTranscript = vars.transcript ? {
  total_duration_seconds: vars.transcript.total_duration_seconds,
  full_text: vars.transcript.full_text,
  words: (vars.transcript.words || []).filter(w => /[.?!]$/.test(w.word))
} : null;

const input = {
  voiceover_mp3_path:     vars.voiceFinalPath,
  voice_package_path:     vars.voicePackagePath,
  topic:                  vars.topic,
  total_duration_seconds: authoritative_duration,
  voice_package:          slimPackage,
  transcript:             slimTranscript
};

const prompt = 'Your input:\n\n' + JSON.stringify(input, null, 2);
// Return slim vars — don't carry scriptText, voicePackage, or transcript through item data
return [{ json: {
  slug:              vars.slug,
  topic:             vars.topic,
  projectDir:        vars.projectDir,
  voiceFinalPath:    vars.voiceFinalPath,
  scriptPath:        vars.scriptPath,
