// Agent call failed: bridge error, HTTP timeout (continueOnFail), or bypassed via IF node
const agentFailed = !inp.output || (inp.exitCode !== undefined && inp.exitCode !== 0);

if (agentFailed) {
  if (fs.existsSync(vars.mediaTimelinePath)) {
    const timeline = JSON.parse(fs.readFileSync(vars.mediaTimelinePath, 'utf-8'));
    console.log('Agent skipped/failed — loaded timeline from disk: ' + (timeline.scenes||[]).length + ' scenes');
    return [{ json: {
      slug:              vars.slug,
      topic:             vars.topic,
      projectDir:        vars.projectDir,
      voiceFinalPath:    vars.voiceFinalPath,
      scriptPath:        vars.scriptPath,
      researchPath:      vars.researchPath,
      voicePackagePath:  vars.voicePackagePath,
      mediaTimelinePath: vars.mediaTimelinePath,
      imageManifestPath: vars.imageManifestPath,
      videoManifestPath: vars.videoManifestPath,
      metadataPath:      vars.metadataPath
    } }];
  }
  throw new Error('Media Placement Agent failed and no timeline on disk. Error: ' + (inp.error || JSON.stringify(inp)));
}

let raw = (inp.output || '').trim();
const m = raw.match(/```(?:json)?\n?([\s\S]*?)```/);
if (m) raw = m[1].trim();

let timeline;
try { timeline = JSON.parse(raw); } catch(e) {
  const s = raw.indexOf('{'), en = raw.lastIndexOf('}');
  if (s >= 0 && en >= 0) {
    try { timeline = JSON.parse(raw.substring(s, en + 1)); } catch(e2) {}
  }
}

if (!timeline) {
  if (fs.existsSync(vars.mediaTimelinePath)) {
    timeline = JSON.parse(fs.readFileSync(vars.mediaTimelinePath, 'utf-8'));
    console.log('Parse failed — loaded timeline from disk: ' + (timeline.scenes||[]).length + ' scenes');
  } else {
    throw new Error('Cannot parse media_timeline.json and no file on disk. Raw: ' + raw.substring(0, 500));
  }
} else {
  fs.writeFileSync(vars.mediaTimelinePath, JSON.stringify(timeline, null, 2), 'utf-8');
