const http = require('http');
const vars = $input.first().json;

const body = JSON.stringify({
  audio_path:  vars.voiceFinalPath,
  output_base: vars.projectDir + '/scripts/transcript'
});

const transcript = await new Promise((resolve, reject) => {
  const options = {
    hostname: 'host.docker.internal',
    port: 3333,
    path: '/transcribe',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(body)
    }
  };
  const req = http.request(options, (res) => {
    let data = '';
    res.on('data', chunk => data += chunk);
    res.on('end', () => {
      if (res.statusCode !== 200) {
        reject(new Error(`Transcribe endpoint returned ${res.statusCode}: ${data.substring(0, 300)}`));
        return;
      }
      try { resolve(JSON.parse(data)); }
      catch(e) { reject(new Error('Invalid JSON from /transcribe: ' + data.substring(0, 200))); }
    });
  });
  req.on('error', reject);
  req.setTimeout(1800000, () => { req.destroy(); reject(new Error('Transcription timed out after 30 min')); });
  req.write(body);
  req.end();
});

console.log(`Transcript: ${transcript.words.length} words, ${transcript.total_duration_seconds.toFixed(1)}s`);
return [{ json: { ...vars, transcript } }];

