const fs   = require('fs');
const vars = $input.first().json;
let manifestExists = false;
if (fs.existsSync(vars.imageManifestPath)) {
  try {
    const m    = JSON.parse(fs.readFileSync(vars.imageManifestPath, 'utf-8'));
    const count = (m.image_prompts || []).length;
    manifestExists = count >= 10;
    if (!manifestExists) console.log('Manifest exists but only ' + count + ' prompts — will regenerate');
  } catch(e) { manifestExists = false; }
}
return [{ json: { ...vars, manifestExists } }];

const fs = require('fs');
const vars = $input.first().json;
const timeline = JSON.parse(fs.readFileSync(vars.mediaTimelinePath, 'utf-8'));
const CHUNK_SIZE = 10;
const imageScenes = (timeline.scenes || []).filter(s => s.visual_type === 'image');
if (imageScenes.length === 0)
  throw new Error('No image scenes found in media timeline');
const totalChunks = Math.ceil(imageScenes.length / CHUNK_SIZE);
const chunks = [];
for (let i = 0; i < totalChunks; i++) {
  chunks.push(imageScenes.slice(i * CHUNK_SIZE, (i + 1) * CHUNK_SIZE));
}
console.log('Splitting ' + imageScenes.length + ' image scenes into ' + totalChunks + ' chunks of up to ' + CHUNK_SIZE);
return chunks.map((chunk, idx) => ({
  json: {
    ...vars,
    chunkIndex:             idx,
    totalChunks:            totalChunks,
    chunkScenes:            chunk,
    imageManifestChunkPath: vars.projectDir + '/scripts/image_manifest_chunk_' + idx + '.json'
  }
}));

const fs   = require('fs');
const vars = $input.first().json;
const sys  = fs.readFileSync('/Users/jneal/n8n_projects/ruins_untold_system_prompts/image_agent.md', 'utf-8');
const chunkInput = {
  topic: vars.topic || '',
  chunk: { index: vars.chunkIndex + 1, total: vars.totalChunks, scene_count: vars.chunkScenes.length },
  image_scenes: vars.chunkScenes
};
const prompt = sys + '\n\n---\n\nGenerate NB2 image prompts for chunk ' + (vars.chunkIndex + 1) + ' of ' + vars.totalChunks + ' only.\n\nInput:\n\n' + JSON.stringify(chunkInput, null, 2);
return [{ json: { ...vars, claudeBody: JSON.stringify({ prompt, model: 'claude-haiku-4-5-20251001', max_tokens: 65536, effort: 'low' }) } }];

const fs   = require('fs');
const vars = $input.first().json;
let allPrompts = [];
let characterRegistry = null;
let i = 0;
while (fs.existsSync(vars.projectDir + '/scripts/image_manifest_chunk_' + i + '.json')) {
  const chunkPath = vars.projectDir + '/scripts/image_manifest_chunk_' + i + '.json';
  const chunk = JSON.parse(fs.readFileSync(chunkPath, 'utf-8'));
  allPrompts = allPrompts.concat(chunk.image_prompts || []);
  if (i === 0 && chunk.character_registry) characterRegistry = chunk.character_registry;
  i++;
}
if (allPrompts.length === 0)
  throw new Error('No prompts found across ' + i + ' chunk files');
const merged = {
  topic: vars.topic || '',
  total_image_scenes: allPrompts.length,
  character_registry: characterRegistry || [],
  image_prompts: allPrompts,
  manifest_stats: { total_image_prompts: allPrompts.length, chunks_merged: i }
};
fs.writeFileSync(vars.imageManifestPath, JSON.stringify(merged, null, 2), 'utf-8');
console.log('image_manifest.json merged: ' + allPrompts.length + ' prompts from ' + i + ' chunks');
return [{ json: { ...vars, imageManifest: merged } }];
